import { prisma } from "@/core/server/prisma";
import { PlanForm } from "@/modules/payments/components/CommerceAdminForms";
export default async function AdminPlansPage() { const plans = await prisma.plan.findMany({ include: { features: { include: { feature: true } } }, orderBy: { order: "asc" } }); return <div><h1 className="text-3xl font-bold">Plans and features</h1><PlanForm /><section className="mt-7 grid gap-3 md:grid-cols-2">{plans.map((plan) => <article key={plan.id} className="rounded-xl border bg-white p-5"><h2 className="text-xl font-bold">{plan.title}</h2><p className="mt-1 text-sm text-slate-600">{plan.code} · {plan.priceAmount / 100} {plan.currency}</p><p className="mt-3 text-sm">{plan.features.filter((item) => item.enabled).map((item) => item.feature.code).join(" · ") || "No features"}</p></article>)}</section></div>; }
